H.background();
const v = H.plot2d({ xMin: -Math.PI, xMax: Math.PI, yMin: -1.5, yMax: 1.5, pad: 50 });
v.grid(); v.axes();
const N = 1 + Math.floor((1 + Math.sin(t * 0.5)) * 5);   // 1..11 harmonics, breathing
const partial = (x) => {
  let s = 0;
  for (let k = 1; k <= N; k++) s += Math.sin((2 * k - 1) * x) / (2 * k - 1);
  return (4 / Math.PI) * s;
};
v.fn((x) => Math.sign(Math.sin(x)) || 0, { color: H.colors.sub, width: 1.5 });
v.fn(partial, { color: H.colors.accent, width: 3 });
H.text("Fourier series of a square wave", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("harmonics N = " + N, 24, 52, { color: H.colors.accent, size: 14 });
H.legend([{ label: "target square", color: H.colors.sub }, { label: "partial sum", color: H.colors.accent }], H.W - 170, 28);

H.background();
const cx = H.W * 0.28, cy = H.H * 0.52, R = Math.min(H.W, H.H) * 0.28;
const th = t * 0.8;
H.circle(cx, cy, R, { stroke: H.colors.grid, width: 1.5 });
H.line(cx - R - 10, cy, cx + R + 10, cy, { color: H.colors.axis, width: 1 });
H.line(cx, cy - R - 10, cx, cy + R + 10, { color: H.colors.axis, width: 1 });
const px = cx + R * Math.cos(th), py = cy - R * Math.sin(th);
H.line(cx, cy, px, py, { color: H.colors.accent2, width: 2 });
H.line(px, py, px, cy, { color: H.colors.good, width: 2, dash: [4, 4] });
H.line(px, py, cx, py, { color: H.colors.accent, width: 2, dash: [4, 4] });
H.circle(px, py, 6, { fill: H.colors.warn });
const v = H.plot2d({ xMin: 0, xMax: 12, yMin: -1.3, yMax: 1.3, box: { x: H.W * 0.56, y: 70, w: H.W * 0.4, h: H.H - 150 } });
v.grid(); v.axes();
v.fn((x) => Math.sin(x), { color: H.colors.good, width: 2.5 });
v.fn((x) => Math.cos(x), { color: H.colors.accent, width: 2.5 });
v.dot(th % 12, Math.sin(th));
H.text("Unit circle → sine & cosine", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("theta = " + (th % (2 * Math.PI)).toFixed(2) + " rad", 24, 52, { color: H.colors.sub, size: 14 });
H.legend([{ label: "sin", color: H.colors.good }, { label: "cos", color: H.colors.accent }], H.W * 0.56, 50);

H.background();
const g = 9.8, v0 = 22, ang = 58 * Math.PI / 180;
const flight = 2 * v0 * Math.sin(ang) / g;
const tau = (t % (flight + 1));
const xr = v0 * Math.cos(ang) * tau;
const yr = Math.max(0, v0 * Math.sin(ang) * tau - 0.5 * g * tau * tau);
const v = H.plot2d({ xMin: 0, xMax: 60, yMin: 0, yMax: 26, pad: 50 });
v.grid(); v.axes();
const path = [];
for (let i = 0; i <= 60; i++) {
  const tt = i / 60 * flight;
  path.push([v0 * Math.cos(ang) * tt, v0 * Math.sin(ang) * tt - 0.5 * g * tt * tt]);
}
v.path(path, { color: H.colors.sub, width: 1.5, dash: [6, 5] });
const vx = v0 * Math.cos(ang), vy = v0 * Math.sin(ang) - g * tau;
v.arrow(xr, yr, xr + vx * 0.25, yr + vy * 0.25, { color: H.colors.good, width: 2 });
v.dot(xr, yr, { r: 7, fill: H.colors.warn });
H.text("Projectile: 22 m/s at 58 deg", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("x = " + xr.toFixed(1) + " m   y = " + yr.toFixed(1) + " m", 24, 52, { color: H.colors.sub, size: 14 });

H.background();
const v = H.plot2d({ xMin: -3.2, xMax: 3.2, yMin: -3, yMax: 5, pad: 50 });
v.grid(); v.axes();
const f = (x) => 0.15 * x * x * x - x;
const df = (x) => 0.45 * x * x - 1;
v.fn(f, { color: H.colors.accent, width: 3 });
const a = 2.6 * Math.sin(t * 0.6);
const slope = df(a);
const tx = (x) => f(a) + slope * (x - a);
v.line(-3.2, tx(-3.2), 3.2, tx(3.2), { color: H.colors.accent2, width: 2.4, dash: [7, 6] });
v.dot(a, f(a), { r: 7 });
H.text("Derivative = slope of the tangent", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("a = " + a.toFixed(2) + "    f'(a) = " + slope.toFixed(2), 24, 52, { color: H.colors.sub, size: 14 });

H.background();
const cam = H.cam3d({ scale: 70, dist: 16, pitch: -0.5, cy: H.H * 0.56 });
cam.yaw = 0.3 * t;
const loss = (x, y) => 0.6 * (x * x + y * y) - 1.1 * Math.exp(-((x - 1) ** 2 + (y - 1) ** 2));
cam.grid(3, 1);
H.surface3d(cam, loss, { xMin: -2.6, xMax: 2.6, yMin: -2.6, yMax: 2.6, nx: 34, ny: 34, alpha: 0.9 });
// A descending point, re-released every few seconds from a corner.
let px = 2.2, py = 2.2;
const steps = Math.floor((t % 6) * 14);
for (let i = 0; i < steps; i++) {
  const gx = 1.2 * px + 1.1 * 2 * (px - 1) * Math.exp(-((px - 1) ** 2 + (py - 1) ** 2));
  const gy = 1.2 * py + 1.1 * 2 * (py - 1) * Math.exp(-((px - 1) ** 2 + (py - 1) ** 2));
  px -= 0.06 * gx; py -= 0.06 * gy;
}
cam.sphere([px, loss(px, py) + 0.15, py], 0.18, { color: H.colors.warn });
cam.axes(3);
H.text("Gradient descent on a loss surface", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("loss = " + loss(px, py).toFixed(3), 24, 52, { color: H.colors.sub, size: 14 });

H.background();
const w = H.W, h = H.H;
const q1 = { x: w * 0.38, y: h * 0.52, s: +1 };
const q2 = { x: w * 0.62, y: h * 0.52, s: -1 };
function field(x, y) {
  let ex = 0, ey = 0;
  for (const q of [q1, q2]) {
    const dx = x - q.x, dy = y - q.y;
    const r2 = dx * dx + dy * dy + 80;
    const r = Math.sqrt(r2);
    const e = q.s / r2;
    ex += e * dx / r; ey += e * dy / r;
  }
  return [ex, ey];
}
// Streamlines seeded in a ring around the + charge.
for (let k = 0; k < 16; k++) {
  const a0 = (k / 16) * H.TAU;
  let x = q1.x + 16 * Math.cos(a0), y = q1.y + 16 * Math.sin(a0);
  const pts = [[x, y]];
  for (let i = 0; i < 220; i++) {
    const [ex, ey] = field(x, y);
    const m = Math.hypot(ex, ey) + 1e-9;
    x += 3 * ex / m; y += 3 * ey / m;
    if (x < 0 || x > w || y < 0 || y > h) break;
    if (Math.hypot(x - q2.x, y - q2.y) < 14) break;
    pts.push([x, y]);
  }
  H.path(pts, { color: H.colors.accent, width: 1.4 });
}
// A test charge advected by the field.
const tt = (t % 6) / 6;
let tx = H.lerp(q1.x, q2.x, 0.15) , ty = q1.y - 70;
for (let i = 0; i < Math.floor(tt * 200); i++) {
  const [ex, ey] = field(tx, ty); const m = Math.hypot(ex, ey) + 1e-9;
  tx += 2.4 * ex / m; ty += 2.4 * ey / m;
}
H.circle(tx, ty, 6, { fill: H.colors.yellow, stroke: H.colors.bg, width: 2 });
H.circle(q1.x, q1.y, 13, { fill: H.colors.warn });
H.circle(q2.x, q2.y, 13, { fill: H.colors.accent2 });
H.text("+", q1.x - 5, q1.y + 5, { color: H.colors.bg, size: 16, weight: 700 });
H.text("-", q2.x - 4, q2.y + 5, { color: H.colors.bg, size: 18, weight: 700 });
H.text("Electric field of a dipole", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("test charge along the field, t = " + (t % 6).toFixed(1) + "s", 24, 52, { color: H.colors.sub, size: 13 });

H.background();
const RC = 1.6, V0 = 5;
const cycle = t % 8;
const charging = cycle < 5;
const tau = charging ? cycle : cycle - 5;
const V = charging ? V0 * (1 - Math.exp(-tau / RC)) : V0 * Math.exp(-tau / RC);
const v = H.plot2d({ xMin: 0, xMax: 5, yMin: 0, yMax: 5.5, box: { x: 70, y: 70, w: H.W * 0.5, h: H.H - 150 } });
v.grid(); v.axes();
v.fn((x) => V0 * (1 - Math.exp(-x / RC)), { color: H.colors.sub, width: 1.5 });
v.line(RC, 0, RC, V0, { color: H.colors.violet, width: 1.5, dash: [5, 5] });
v.dot(tau, V, { r: 7, fill: H.colors.good });
v.text("t = RC", RC + 0.1, 0.5, { color: H.colors.violet, size: 12 });
// A little circuit + a capacitor whose fill tracks V.
const bx = H.W * 0.68, by = 120, bw = 220, bh = 260;
H.rect(bx, by, bw, bh, { stroke: H.colors.axis, width: 2, radius: 8 });
H.text("battery", bx + 10, by + 24, { color: H.colors.sub, size: 12 });
const capX = bx + bw - 60, capY = by + 60, capH = 140;
H.rect(capX, capY, 36, capH, { stroke: H.colors.accent, width: 2 });
H.rect(capX + 3, capY + capH - capH * (V / V0) + 3, 30, capH * (V / V0) - 6, { fill: H.colors.accent });
H.text("Q", capX + 44, capY + capH / 2, { color: H.colors.accent, size: 14 });
H.text("RC circuit: charging a capacitor", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text((charging ? "charging" : "discharging") + "   V = " + V.toFixed(2) + " V", 24, 52, { color: H.colors.sub, size: 14 });

H.background();
const cam = H.cam3d({ scale: 34, dist: 18, pitch: -0.2 });
cam.yaw = 0.5 * t;
const balls = [];
const N = 34;
for (let i = 0; i < N; i++) {
  const s = i / (N - 1);
  const ang = s * H.TAU * 2.1 + t * 0.3;
  const ypos = (s - 0.5) * 9;
  const a = [2.1 * Math.cos(ang), ypos, 2.1 * Math.sin(ang)];
  const b = [-2.1 * Math.cos(ang), ypos, -2.1 * Math.sin(ang)];
  balls.push({ p: a, color: H.colors.accent, r: 0.32 });
  balls.push({ p: b, color: H.colors.accent2, r: 0.32 });
  if (i % 3 === 0) cam.line(a, b, { color: H.colors.sub, width: 1.6 });
}
balls
  .map((o) => ({ ...o, depth: cam.project(o.p).depth }))
  .sort((a, b) => b.depth - a.depth)
  .forEach((o) => cam.sphere(o.p, o.r, { color: o.color }));
H.text("DNA double helix", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("two antiparallel strands joined by base pairs", 24, 52, { color: H.colors.sub, size: 13 });

H.background();
// --- Kepler's first & second law: elliptical orbit + equal areas in equal times ---
const a = 5.2;            // semi-major axis (data units)
const e = 0.6;            // eccentricity
const b = a * Math.sqrt(1 - e * e);   // semi-minor axis
const c = a * e;          // focus offset from center
const v = H.plot2d({ xMin: -7.2, xMax: 7.2, yMin: -4.6, yMax: 4.6, pad: 50 });
v.grid(); v.axes();

// Star sits at the focus (origin). Center of the ellipse is at (-c, 0).
const cxData = -c, cyData = 0;
// Draw the full ellipse path.
const ell = [];
const NE = 160;
for (let i = 0; i <= NE; i++) {
  const th = (i / NE) * H.TAU;
  ell.push([cxData + a * Math.cos(th), cyData + b * Math.sin(th)]);
}
v.path(ell, { color: H.colors.accent, width: 2.4 });

// Solve Kepler's equation M = E - e sin E for the eccentric anomaly E.
// Mean motion: full period = 6s of sim time, so M sweeps uniformly with t.
const period = 6;
const M = ((t % period) / period) * H.TAU;
let E = M;                          // Newton iteration (few steps, converges fast)
for (let k = 0; k < 6; k++) {
  E -= (E - e * Math.sin(E) - M) / (1 - e * Math.cos(E));
}
// Planet position on the ellipse (focus at origin).
const px = cxData + a * Math.cos(E);
const py = cyData + b * Math.sin(E);

// Equal-area swept sector over a fixed slice of the period, ending at "now".
const dM = H.TAU * 0.10;            // mean-anomaly width of the highlighted sweep
const swept = [[0, 0]];
const SEG = 28;
for (let i = 0; i <= SEG; i++) {
  const Mi = M - dM + (dM * i) / SEG;
  let Ei = Mi;
  for (let k = 0; k < 5; k++) {
    Ei -= (Ei - e * Math.sin(Ei) - Mi) / (1 - e * Math.cos(Ei));
  }
  swept.push([cxData + a * Math.cos(Ei), cyData + b * Math.sin(Ei)]);
}
v.path(swept, { color: H.colors.accent2, width: 1, fill: "rgba(244,162,89,0.32)", close: true });

// Radius line star -> planet, and the star itself at the focus.
v.line(0, 0, px, py, { color: H.colors.sub, width: 1.4, dash: [5, 5] });
v.circle(0, 0, 9, { fill: H.colors.yellow, stroke: "#a8791f", width: 1.5 });
v.dot(px, py, { r: 6, fill: H.colors.accent, stroke: H.colors.bg });
// Mark the empty (other) focus too.
v.circle(-2 * c, 0, 3, { fill: H.colors.sub });

// Live numbers: orbital radius r and instantaneous speed (vis-viva, GM=1).
const r = Math.hypot(px, py);
const speed = Math.sqrt(Math.max(0, 2 / r - 1 / a));   // vis-viva, never negative
const phaseName = E < Math.PI ? "speeding up toward perihelion" : "slowing toward aphelion";

H.text("Kepler's Laws: elliptical orbit & equal areas", 24, 30,
  { color: H.colors.ink, size: 18, weight: 700 });
H.text("Orange sectors swept in equal times have equal area (2nd law).",
  24, 52, { color: H.colors.sub, size: 13 });
H.text("r = " + r.toFixed(2) + " AU", 24, H.H - 54, { color: H.colors.accent2, size: 14 });
H.text("v = " + speed.toFixed(2) + "  (vis-viva, GM=1)", 24, H.H - 34,
  { color: H.colors.good, size: 14 });
H.text("e = " + e.toFixed(2) + "   " + phaseName, 24, H.H - 14,
  { color: H.colors.sub, size: 12 });
H.legend([
  { label: "orbit (ellipse)", color: H.colors.accent },
  { label: "star at focus", color: H.colors.yellow },
  { label: "swept area", color: H.colors.accent2 },
], H.W - 200, 30);

H.background();
// --- Moon phases (3D): the Moon orbiting Earth, lit from one side by the Sun ---
const cam = H.cam3d({ scale: 46, dist: 17, pitch: -0.62, cy: H.H * 0.52 });
cam.yaw = 0.18 * t;                 // gentle default spin so it reads as 3D
cam.grid(7, 1);

// Sun is far away in the +X direction: light rays point toward -X.
const sunDir = [1, 0, 0];           // unit vector FROM scene TOWARD the Sun
const orbitR = 4.0;                 // Moon's orbital radius about Earth (data units)
const period = 12;                  // seconds per synodic cycle
const phase = ((t % period) / period) * H.TAU;   // 0..TAU around the orbit
// Moon position in the ecliptic plane (x/z ground plane; y is up).
const mx = orbitR * Math.cos(phase);
const mz = orbitR * Math.sin(phase);
const moonPos = [mx, 0, mz];

// Draw the orbit ring of the Moon.
const ring = [];
const NR = 96;
for (let i = 0; i <= NR; i++) {
  const th = (i / NR) * H.TAU;
  ring.push([orbitR * Math.cos(th), 0, orbitR * Math.sin(th)]);
}
cam.path(ring, { color: H.colors.grid, width: 1.4 });

// Sunlight direction indicator: a long arrow sweeping in across the scene.
const sunHead = cam.project([-orbitR - 1.4, 0, 0]);
const sunTail = cam.project([-6.2, 0, 0]);
H.arrow(sunTail.x, sunTail.y, sunHead.x, sunHead.y, { color: H.colors.yellow, width: 2 });

// Phase angle: angle between Sun direction and Earth->Moon direction.
// Illuminated fraction = (1 - cos(elongation)) / 2.
const moonHat = [Math.cos(phase), 0, Math.sin(phase)];
const cosElong = moonHat[0] * sunDir[0] + moonHat[2] * sunDir[2];
const illum = (1 - cosElong) / 2;   // 0 = new moon, 1 = full moon
const elong = Math.acos(H.clamp(cosElong, -1, 1));

// Depth-sort the bodies and draw far-to-near.
const bodies = [
  { p: [0, 0, 0], r: 1.05, color: H.colors.accent },
  { p: moonPos, r: 0.55, color: "#cdd3e0" },
];
bodies
  .map((o) => ({ p: o.p, r: o.r, color: o.color, depth: cam.project(o.p).depth }))
  .sort((a, b) => b.depth - a.depth)
  .forEach((o) => cam.sphere(o.p, o.r, { color: o.color }));

// Terminator shading on the Moon: a dark cap on the side facing away from the
// Sun, sized by the unlit fraction, drawn in screen space.
const mProj = cam.project(moonPos);
const moonRpx = Math.max(4, 0.55 * 46 * mProj.f);
const darkCenter = [moonPos[0] - sunDir[0] * 0.55, 0, moonPos[2] - sunDir[2] * 0.55];
const dProj = cam.project(darkCenter);
H.circle(dProj.x, dProj.y, moonRpx * (0.45 + 0.55 * (1 - illum)),
  { fill: "rgba(8,10,24,0.55)" });

// As-seen-from-Earth phase disk in the corner (crescent/gibbous).
const diskX = H.W - 90, diskY = 96, diskR = 34;
H.circle(diskX, diskY, diskR + 4, { fill: "#11182b", stroke: H.colors.grid, width: 1.5 });
H.circle(diskX, diskY, diskR, { fill: "#1a2236" });
const waxing = Math.sin(phase) >= 0 ? 1 : -1;
const lit = [];
const NP = 40;
for (let i = 0; i <= NP; i++) {
  const ang = -Math.PI / 2 + (Math.PI * i) / NP;
  lit.push([diskX + waxing * diskR * Math.cos(ang), diskY + diskR * Math.sin(ang)]);
}
const termW = diskR * (1 - 2 * illum);
for (let i = NP; i >= 0; i--) {
  const ang = -Math.PI / 2 + (Math.PI * i) / NP;
  lit.push([diskX + waxing * termW * Math.cos(ang), diskY + diskR * Math.sin(ang)]);
}
H.path(lit, { color: "none", fill: H.colors.yellow, close: true });

let phaseName;
if (illum < 0.04) phaseName = "New Moon";
else if (illum > 0.96) phaseName = "Full Moon";
else if (Math.abs(illum - 0.5) < 0.06) phaseName = (waxing > 0 ? "First" : "Last") + " Quarter";
else if (illum < 0.5) phaseName = (waxing > 0 ? "Waxing" : "Waning") + " Crescent";
else phaseName = (waxing > 0 ? "Waxing" : "Waning") + " Gibbous";

cam.axes(5);
H.text("Moon Phases: lighting geometry in 3D", 24, 30,
  { color: H.colors.ink, size: 18, weight: 700 });
H.text("The Sun lights one hemisphere; phase = how much of it we see from Earth.",
  24, 52, { color: H.colors.sub, size: 13 });
H.text("illuminated = " + (illum * 100).toFixed(0) + "%", 24, H.H - 54,
  { color: H.colors.yellow, size: 14 });
H.text("elongation = " + (elong * 180 / Math.PI).toFixed(0) + " deg", 24, H.H - 34,
  { color: H.colors.sub, size: 13 });
H.text("phase: " + phaseName, 24, H.H - 14, { color: H.colors.accent, size: 14, weight: 700 });
H.legend([
  { label: "Earth", color: H.colors.accent },
  { label: "Moon", color: "#cdd3e0" },
  { label: "sunlight", color: H.colors.yellow },
], H.W - 170, H.H - 80);

H.background();
// --- Inverse-square gravity: the potential well and a test mass orbiting in it ---
const cam = H.cam3d({ scale: 30, dist: 17, pitch: -0.6, cy: H.H * 0.56 });
cam.yaw = 0.3 * t;                  // slow spin so the well reads as 3D
cam.grid(6, 2);

const GM = 6.0;                     // gravitational parameter
const soft = 0.45;                  // softening so the funnel stays finite at r=0
// Potential height: Phi = -GM / sqrt(r^2 + soft^2), scaled to a visible depth.
H.surface3d(cam, (x, y) => {
  const r2 = x * x + y * y;
  return (-GM / Math.sqrt(r2 + soft * soft)) * 0.95 + 7.5; // lift so it's in frame
}, { xMin: -5.5, xMax: 5.5, yMin: -5.5, yMax: 5.5, nx: 40, ny: 40,
     hueMin: 215, hueMax: 280, alpha: 0.94 });

// Test mass on a circular orbit at radius rOrb, sitting on the funnel wall.
const rOrb = 2.6;
const ang = t * 0.9;
const ox = rOrb * Math.cos(ang);
const oz = rOrb * Math.sin(ang);
const height = (-GM / Math.sqrt(rOrb * rOrb + soft * soft)) * 0.95 + 7.5;
const massPos = [ox, height + 0.35, oz];
cam.sphere(massPos, 0.32, { color: H.colors.accent2 });
// Central mass at the bottom of the well.
const wellBottom = (-GM / Math.sqrt(soft * soft)) * 0.95 + 7.5;
cam.sphere([0, wellBottom + 0.3, 0], 0.5, { color: H.colors.yellow });

// Inward gravitational force arrow on the test mass.
const g = GM / (rOrb * rOrb);
const ux = -Math.cos(ang), uz = -Math.sin(ang);
const tip = [ox + ux * g * 0.18, massPos[1], oz + uz * g * 0.18];
const aP = cam.project(massPos);
const bP = cam.project(tip);
H.arrow(aP.x, aP.y, bP.x, bP.y, { color: H.colors.good, width: 2.4 });

cam.axes(5);

// 2D inset: g(r) = GM/r^2 falling off, with the current radius marked.
const v = H.plot2d({
  xMin: 0.4, xMax: 6, yMin: 0, yMax: 12,
  box: { x: H.W - 230, y: 64, w: 200, h: 130 },
});
v.grid(); v.axes();
v.fn((rr) => GM / (rr * rr), { color: H.colors.accent, width: 2.4 });
v.dot(rOrb, g, { r: 5, fill: H.colors.accent2 });
v.line(rOrb, 0, rOrb, g, { color: H.colors.sub, width: 1, dash: [3, 4] });
H.text("g(r) = GM/r^2", H.W - 224, 58, { color: H.colors.accent, size: 12 });

H.text("Inverse-square gravity & the potential well", 24, 30,
  { color: H.colors.ink, size: 18, weight: 700 });
H.text("Phi = -GM/r forms a funnel; force g = GM/r^2 grows steeply as r shrinks.",
  24, 52, { color: H.colors.sub, size: 13 });
