H.background();
const w = H.W, h = H.H;
// --- Sieve of Eratosthenes on a 10x10 grid of the integers 2..101 ---
const N = 100;            // numbers shown: 2 .. 101
const cols = 10, rows = 10;
const first = 2;
// Rebuild the sieve state up to the "stage" the animation has reached.
// stage advances roughly one prime every ~1.6s and loops.
const primesToProcess = [2, 3, 5, 7]; // sqrt(101) < 11, so these suffice
const cycle = primesToProcess.length + 1;
const stageF = (t / 1.6) % cycle;     // 0..cycle, fractional
const stage = Math.floor(stageF);     // which prime index we're on
const subt = stageF - stage;          // progress within this prime's pass

// composite[k] === true  -> crossed out (k is the integer 2..101)
const composite = new Array(first + N).fill(false);
const activePrime = stage < primesToProcess.length ? primesToProcess[stage] : 0;
// Fully cross out all multiples of every prime strictly before the active one.
for (let s = 0; s < stage && s < primesToProcess.length; s++){
  const p = primesToProcess[s];
  for (let m = p * p; m < first + N; m += p) composite[m] = true;
}
// Partially reveal the active prime's multiples as subt grows 0->1.
let sweepHit = -1;
if (activePrime > 0){
  const mults = [];
  for (let m = activePrime * activePrime; m < first + N; m += activePrime) mults.push(m);
  const reveal = Math.floor(H.ease(subt) * (mults.length + 0.999));
  for (let i = 0; i < reveal && i < mults.length; i++) composite[mults[i]] = true;
  if (reveal > 0 && reveal <= mults.length) sweepHit = mults[reveal - 1];
}

// --- layout the grid cell box ---
const gx = 54, gy = 96;
const gw = Math.min(w - 110, h - 150);
const cell = gw / cols;
const gh = cell * rows;

let primeCount = 0;
for (let i = 0; i < N; i++){
  const n = first + i;
  const c = i % cols;
  const r = Math.floor(i / cols);
  const x = gx + c * cell;
  const y = gy + r * cell;
  const isComp = composite[n];
  const isActivePrime = (n === activePrime);
  if (!isComp) primeCount++;
  // cell background
  let fill = H.colors.panel;
  if (isActivePrime) fill = "#274064";
  else if (n === sweepHit) fill = "#3a2a44";
  H.rect(x + 2, y + 2, cell - 4, cell - 4,
    { fill, stroke: isComp ? "#202a44" : H.colors.grid, width: 1, radius: 5 });
  // number
  const tcol = isComp ? "#4f5d80" : (isActivePrime ? H.colors.yellow : H.colors.ink);
  H.text(String(n), x + cell / 2, y + cell / 2 + 4,
    { color: tcol, size: Math.max(9, cell * 0.34), align: "center", weight: isComp ? 400 : 600 });
  // strike-through for composites
  if (isComp){
    const pad = cell * 0.22;
    H.line(x + pad, y + pad, x + cell - pad, y + cell - pad,
      { color: H.colors.warn, width: 1.6 });
  }
}

// Pulsing ring on the current prime being sieved.
if (activePrime > 0){
  const idx = activePrime - first;
  const c = idx % cols, r = Math.floor(idx / cols);
  const cxp = gx + c * cell + cell / 2;
  const cyp = gy + r * cell + cell / 2;
  const pr = cell * 0.5 + 4 + 2 * Math.sin(t * 6);
  H.circle(cxp, cyp, pr, { stroke: H.colors.yellow, width: 2.4 });
}

