H.background();
const w = H.W, h = H.H;
// Fibonacci sequence
const fib = [1, 1];
for (let i = 2; i < 11; i++) fib.push(fib[i - 1] + fib[i - 2]);
const PHI = (1 + Math.sqrt(5)) / 2;

// How many squares are "grown in" - sweeps up then resets, looping.
const maxSq = 9;
const period = maxSq + 2.0;
const tt = (t / 1.1) % period;
const grown = Math.min(maxSq, Math.floor(tt));     // fully drawn squares
const partial = Math.min(1, tt - grown);           // growth of the next square

// Build square placements by spiraling out: each new square sits on a side
// of the running bounding box. Directions cycle: right, up, left, down.
const squares = [];
// Canonical Fibonacci tiling: seed a 1x1 square at the origin, then attach
// each successive square to a side of the running bounding box.
const s0 = fib[0];
squares.push({ x: 0, y: 0, s: s0, dir: 0, idx: 0 });
let minx = 0, miny = 0, maxx = s0, maxy = s0;
for (let i = 1; i < fib.length; i++){
  const s = fib[i];
  let nx, ny;
  // attach on a side of current bounding box, going counter-clockwise
  const d = i % 4;
  if (d === 1){ nx = minx - s; ny = miny; }        // left
  else if (d === 2){ nx = minx; ny = miny - s; }   // bottom
  else if (d === 3){ nx = maxx; ny = miny; }        // right (aligned bottom)
  else { nx = minx; ny = maxy; }                    // top
  squares.push({ x: nx, y: ny, s, dir: d, idx: i });
  minx = Math.min(minx, nx); miny = Math.min(miny, ny);
  maxx = Math.max(maxx, nx + s); maxy = Math.max(maxy, ny + s);
}

// Fit the bounding box of grown squares into a centered viewport.
let bx0 = Infinity, by0 = Infinity, bx1 = -Infinity, by1 = -Infinity;
for (let i = 0; i <= grown && i < squares.length; i++){
  const q = squares[i];
  bx0 = Math.min(bx0, q.x); by0 = Math.min(by0, q.y);
  bx1 = Math.max(bx1, q.x + q.s); by1 = Math.max(by1, q.y + q.s);
}
if (!Number.isFinite(bx0)){ bx0 = 0; by0 = 0; bx1 = 1; by1 = 1; }
const bw = Math.max(1e-6, bx1 - bx0), bh = Math.max(1e-6, by1 - by0);
const vpw = w * 0.56, vph = h * 0.72;
const vx = w * 0.05, vy = h * 0.16;
const sc = Math.min(vpw / bw, vph / bh);
// center inside viewport
const offx = vx + (vpw - bw * sc) / 2;
const offy = vy + (vph - bh * sc) / 2;
// world (fib units, y up) -> screen (y down)
const SX = (wx) => offx + (wx - bx0) * sc;
const SY = (wy) => offy + (by1 - wy) * sc;

// draw each square + its quarter-circle arc
for (let i = 0; i <= grown && i < squares.length; i++){
  const q = squares[i];
  const grow = (i === grown) ? partial : 1;
  const col = H.color(i % H.palette.length);
  // square (optionally growing from a corner)
  const sx = SX(q.x), sy = SY(q.y + q.s);
  const pw = q.s * sc, ph = q.s * sc;
  H.rect(sx, sy, pw * grow, ph * grow, {
    stroke: col, width: 2, fill: H.hsl(200 + i * 14, 45, 22, 0.35), radius: 0,
  });
  H.text("F=" + q.s, sx + 6, sy + 16, { color: col, size: Math.min(15, 6 + pw * 0.06) });

  // quarter-circle arc spiraling through the square (full square only)
  if (grow >= 0.999){
    const d = q.dir;
    let ccx, ccy, a0;
    // y is up in world; convert to screen for arc center
    if (d === 0){ ccx = q.x;        ccy = q.y;        a0 = 0;          }   // first / top
    else if (d === 1){ ccx = q.x + q.s; ccy = q.y;        a0 = H.PI / 2;  } // left
    else if (d === 2){ ccx = q.x + q.s; ccy = q.y + q.s;  a0 = H.PI;      } // bottom
    else { ccx = q.x;        ccy = q.y + q.s;  a0 = -H.PI / 2; }            // right
    const pts = [];
    const seg = 22;
    for (let j = 0; j <= seg; j++){
      const a = a0 + (j / seg) * (H.PI / 2);
      const ax = ccx + Math.cos(a) * q.s;
      const ay = ccy + Math.sin(a) * q.s;
      pts.push([SX(ax), SY(ay)]);
    }
    H.path(pts, { color: H.colors.yellow, width: 3 });
  }
}

// moving dot tracing the very tip of the spiral
if (grown >= 1){
  const q = squares[Math.min(grown, squares.length - 1)];
  const d = q.dir;
  let ccx, ccy, a0;
  if (d === 0){ ccx = q.x; ccy = q.y; a0 = 0; }
  else if (d === 1){ ccx = q.x + q.s; ccy = q.y; a0 = H.PI / 2; }
  else if (d === 2){ ccx = q.x + q.s; ccy = q.y + q.s; a0 = H.PI; }
  else { ccx = q.x; ccy = q.y + q.s; a0 = -H.PI / 2; }
  const a = a0 + H.ease(partial) * (H.PI / 2);
  const ax = ccx + Math.cos(a) * q.s, ay = ccy + Math.sin(a) * q.s;
  H.circle(SX(ax), SY(ay), 6, { fill: H.colors.good, stroke: H.colors.bg, width: 2 });
}

