// Sample size n sweeps up and down over time so the sampling distribution
// of the sample mean visibly narrows (CLT: SE = sigma / sqrt(n)).
const sigma = 1.0;            // population standard deviation
const mu = 0;                 // true mean
const nMin = 1, nMax = 40;
const phase = (Math.sin(t * 0.5) + 1) / 2;          // 0..1, smooth
const nF = H.lerp(nMin, nMax, phase);
const n = Math.max(1, Math.round(nF));
const se = sigma / Math.sqrt(n);                    // standard error
const seSafe = Math.max(se, 1e-3);

// A ridge of normal curves, one per "step" of n along the z axis, each
// scaled to the standard error at that n. Draw as a height surface:
// height(x, z) = peak of a gaussian whose width depends on n(z).
const xMin = -4, xMax = 4;
