H.surface3d(cam, (x, z) => {
  // map z -> an n value so the back of the ridge is large-n (narrow/tall)
  const frac = (z - zMin) / (zMax - zMin);
  const nz = H.lerp(nMin, nMax, frac);
  const sez = Math.max(sigma / Math.sqrt(nz), 1e-3);
  const g = Math.exp(-0.5 * ((x - mu) / sez) * ((x - mu) / sez));
  return (g / sez) * 0.55;     // taller + narrower as n grows
}, { xMin: xMin, xMax: xMax, yMin: zMin, yMax: zMax, nx: 40, ny: 40,
