  // deterministic "noise" from trig hashing of i
  const noise = 1.6 * Math.sin(i * 12.9898) + 1.1 * Math.cos(i * 4.231);
  const y = trueM * x + trueB + noise;
  xs.push(x); ys.push(y);
}

// Closed-form ordinary-least-squares fit of the fixed cloud.
let sx = 0, sy = 0, sxx = 0, sxy = 0;
for (let i = 0; i < N; i++) {
  sx += xs[i]; sy += ys[i]; sxx += xs[i] * xs[i]; sxy += xs[i] * ys[i];
}
const denom = N * sxx - sx * sx;
const mBest = denom !== 0 ? (N * sxy - sx * sy) / denom : 0;
const bBest = (sy - mBest * sx) / N;

