// Beta(a,b) density on theta in [0,1] — conjugate prior for a coin's bias.
// log-gamma via Lanczos for a normalized, accurate Beta pdf.
function logGamma(z) {
  const g = 7;
  const c = [0.99999999999980993, 676.5203681218851, -1259.1392167224028,
    771.32342877765313, -176.61502916214059, 12.507343278686905,
    -0.13857109526572012, 9.9843695780195716e-6, 1.5056327351493116e-7];
  if (z < 0.5) {
    return Math.log(Math.PI / Math.sin(Math.PI * z)) - logGamma(1 - z);
  }
  z -= 1;
  let x = c[0];
  for (let i = 1; i < g + 2; i++) x += c[i] / (z + i);
  const tt = z + g + 0.5;
  return 0.5 * Math.log(2 * Math.PI) + (z + 0.5) * Math.log(tt) - tt + Math.log(x);
}
function betaPdf(x, a, b) {
  if (x <= 0 || x >= 1) return 0;
  const lb = logGamma(a + b) - logGamma(a) - logGamma(b)
    + (a - 1) * Math.log(x) + (b - 1) * Math.log(1 - x);
  const y = Math.exp(lb);
  return Number.isFinite(y) ? y : 0;
}

// Prior Beta(2,2). Stream in coin flips over time; each flip updates a,b.
const trueP = 0.7;                 // hidden bias we are learning
const a0 = 2, b0 = 2;
const maxFlips = 60;
const flips = Math.min(maxFlips, Math.floor((t % 14) / 14 * (maxFlips + 1)));
let heads = 0;
for (let i = 0; i < flips; i++) {
  // deterministic stream: ~trueP fraction are heads
  const u = (Math.sin(i * 78.233) * 43758.5453);
  const frac = u - Math.floor(u);     // 0..1 pseudo-random
  if (frac < trueP) heads++;
}
const tails = flips - heads;
const a = a0 + heads;
const b = b0 + tails;
const postMean = a / (a + b);

// Draw prior (dim) and posterior (bright).
v.fn((x) => betaPdf(x, a0, b0), { color: H.colors.sub, width: 2 });
v.fn((x) => betaPdf(x, a, b), { color: H.colors.violet, width: 3.4 });

// Mark the true bias and the posterior mean.
v.line(trueP, 0, trueP, 6, { color: H.colors.good, width: 2, dash: [6, 5] });
const peakY = betaPdf(postMean, a, b);
v.dot(postMean, Math.min(peakY, 6), { r: 6, fill: H.colors.accent2 });

H.text("Bayesian update: learning a coin's bias", 24, 30,
  { color: H.colors.ink, size: 18, weight: 700 });
H.text("Each flip reshapes Beta(a,b) toward the true value.", 24, 52,
  { color: H.colors.sub, size: 13 });
H.text("flips = " + flips + "  (H " + heads + " / T " + tails + ")", 24, 76,
  { color: H.colors.sub, size: 13 });
H.text("posterior Beta(" + a + ", " + b + ")   mean = " + postMean.toFixed(3),
  24, 96, { color: H.colors.violet, size: 13 });
H.text("true p = " + trueP.toFixed(2), v.X(trueP) + 6, v.Y(5.4),
  { color: H.colors.good, size: 12 });
H.legend([
  { label: "prior Beta(2,2)", color: H.colors.sub },
  { label: "posterior", color: H.colors.violet },
  { label: "true bias", color: H.colors.good },
  { label: "posterior mean", color: H.colors.accent2 },
], H.W - 190, 40);

H.background();
const cam = H.cam3d({ scale: 40, dist: 15, pitch: -0.5, cy: H.H * 0.56 });
cam.yaw = 0.3 * t;
const f = (x, y) =>
  1.6 * Math.exp(-((x - 1) * (x - 1) + (y - 1) * (y - 1)) / 2.2) +
  1.1 * Math.exp(-((x + 1.4) * (x + 1.4) + (y + 1.2) * (y + 1.2)) / 1.8);
cam.grid(3.2, 0.8);
H.surface3d(cam, (x, y) => f(x, y) * 1.4, {
  xMin: -3, xMax: 3, yMin: -3, yMax: 3, nx: 40, ny: 40, hueMin: 205, hueMax: 35,
});
const px = 1.8 * Math.cos(t * 0.7);
const py = 1.8 * Math.sin(t * 0.7);
const h = 1e-3;
const fx = (f(px + h, py) - f(px - h, py)) / (2 * h);
const fy = (f(px, py + h) - f(px, py - h)) / (2 * h);
const gmag = Math.sqrt(fx * fx + fy * fy);
const zp = f(px, py) * 1.4;
cam.line([px, 0, py], [px, zp, py], { color: H.colors.sub, width: 1.4 });
cam.sphere([px, zp, py], 0.16, { color: H.colors.warn });
const s = 0.7;
const tip = [px + fx * s, 0.04, py + fy * s];
const a0 = cam.project([px, 0.04, py]);
const a1 = cam.project(tip);
H.arrow(a0.x, a0.y, a1.x, a1.y, { color: H.colors.yellow, width: 3, head: 11 });
cam.line([px, 0.04, py], [px, zp, py], { color: H.colors.warn, width: 1, dash: [4, 4] });
cam.axes(3.4);
H.text("Surface z = f(x, y) and its gradient", 24, 32, { color: H.colors.ink, size: 18, weight: 700 });
H.text("grad f points uphill in the x-y plane; its length is the steepest slope.", 24, 54, { color: H.colors.sub, size: 13 });
H.text("point  (x, y) = (" + px.toFixed(2) + ", " + py.toFixed(2) + ")", 24, 84, { color: H.colors.ink, size: 13 });
H.text("grad f = (" + fx.toFixed(2) + ", " + fy.toFixed(2) + ")   |grad f| = " + gmag.toFixed(2), 24, 104, { color: H.colors.yellow, size: 13 });
H.legend([
  { label: "surface z = f(x,y)", color: H.colors.accent },
  { label: "point on surface", color: H.colors.warn },
  { label: "grad f (gradient on x-y plane)", color: H.colors.yellow },
], 24, H.H - 64);

H.background();
const cam = H.cam3d({ scale: 42, dist: 15, pitch: -0.5, cy: H.H * 0.58 });
cam.yaw = 0.25 * t;
const L = (x, y) =>
  0.35 * (x * x + y * y) + 0.5 * Math.sin(1.3 * x) * Math.cos(1.3 * y) + 0.5;
cam.grid(3, 1);
H.surface3d(cam, (x, y) => L(x, y), {
  xMin: -3, xMax: 3, yMin: -3, yMax: 3, nx: 40, ny: 40, hueMin: 265, hueMax: 150, alpha: 0.9,
});
const lr = 0.18;
const eps = 1e-3;
const grad = (x, y) => [
  (L(x + eps, y) - L(x - eps, y)) / (2 * eps),
  (L(x, y + eps) - L(x, y - eps)) / (2 * eps),
];
const totalSteps = 60;
const k = Math.min(totalSteps, Math.floor((t % 9) / 9 * totalSteps));
let x = 2.5, y = -2.3;
const trail = [[x, L(x, y), y]];
for (let i = 0; i < k; i++) {
  const g0 = grad(x, y);
  x -= lr * g0[0];
  y -= lr * g0[1];
  if (!Number.isFinite(x) || !Number.isFinite(y)) break;
  x = H.clamp(x, -3, 3); y = H.clamp(y, -3, 3);
  trail.push([x, L(x, y), y]);
}
const loss = L(x, y);
const g = grad(x, y);
const gmag = Math.sqrt(g[0] * g[0] + g[1] * g[1]);
cam.path(trail, { color: H.colors.yellow, width: 3 });
cam.path(trail.map((p) => [p[0], 0.02, p[2]]), { color: H.colors.grid, width: 1.5 });
cam.sphere([x, loss, y], 0.18, { color: H.colors.warn });
cam.line([x, 0, y], [x, loss, y], { color: H.colors.sub, width: 1, dash: [4, 4] });
cam.axes(3.4);
H.text("Gradient descent on a loss surface", 24, 32, { color: H.colors.ink, size: 18, weight: 700 });
H.text("Each step moves against grad L (downhill). The ball settles in a minimum.", 24, 54, { color: H.colors.sub, size: 13 });
H.text("step " + k + " / " + totalSteps + "    learning rate = " + lr.toFixed(2), 24, 84, { color: H.colors.ink, size: 13 });
H.text("L(x, y) = " + loss.toFixed(3) + "    |grad L| = " + gmag.toFixed(3), 24, 104, { color: H.colors.yellow, size: 13 });
H.legend([
  { label: "loss surface L(x,y)", color: H.colors.violet },
  { label: "descent path", color: H.colors.yellow },
  { label: "current iterate", color: H.colors.warn },
], 24, H.H - 64);

H.background();
const v = H.plot2d({ xMin: -5, xMax: 5, yMin: -3.2, yMax: 3.2, pad: 50 });
v.grid();
v.axes();
const Fx = (x, y) => 0.6 * x - 0.9 * y + 0.4 * Math.sin(0.8 * y);
const Fy = (x, y) => 0.9 * x + 0.6 * y;
const step = 1.0;
for (let gx = -4.5; gx <= 4.5 + 1e-9; gx += step) {
  for (let gy = -3; gy <= 3 + 1e-9; gy += step) {
    const fx = Fx(gx, gy), fy = Fy(gx, gy);
    const mag = Math.sqrt(fx * fx + fy * fy) + 1e-9;
    const sc = 0.42 / Math.max(1, mag * 0.5);
    const hue = H.clamp(210 - mag * 14, 20, 210);
    v.arrow(gx, gy, gx + fx * sc, gy + fy * sc, { color: H.hsl(hue, 80, 62), width: 1.6, head: 6 });
  }
}
const NP = 26;
for (let i = 0; i < NP; i++) {
  const ang = (i / NP) * H.TAU;
  let x = 3.4 * Math.cos(ang), y = 2.0 * Math.sin(ang);
  const dt = 0.05;
  const phase = (t * 0.9 + i * 0.13) % 1;
  const adv = Math.floor(phase * 10) + 3;
  for (let sN = 0; sN < adv && sN < 30; sN++) {
    const fx = Fx(x, y), fy = Fy(x, y);
    x += fx * dt; y += fy * dt;
    if (!Number.isFinite(x) || !Number.isFinite(y)) break;
  }
  if (Math.abs(x) < 5 && Math.abs(y) < 3.2)
    v.dot(x, y, { r: 3, fill: H.colors.good, stroke: H.colors.bg });
}
const sx = 2.6 * Math.cos(t * 0.6);
const sy = 1.7 * Math.sin(t * 0.6);
const e = 1e-3;
const dFxdx = (Fx(sx + e, sy) - Fx(sx - e, sy)) / (2 * e);
const dFydy = (Fy(sx, sy + e) - Fy(sx, sy - e)) / (2 * e);
const dFydx = (Fy(sx + e, sy) - Fy(sx - e, sy)) / (2 * e);
const dFxdy = (Fx(sx, sy + e) - Fx(sx, sy - e)) / (2 * e);
const div = dFxdx + dFydy;
const curl = dFydx - dFxdy;
const ua = t * 0.8;
const ux = Math.cos(ua), uy = Math.sin(ua);
const dirArrowLen = 1.0;
v.arrow(sx, sy, sx + ux * dirArrowLen, sy + uy * dirArrowLen, { color: H.colors.yellow, width: 2.6, head: 9 });
const ringR = 26 + 6 * Math.sin(t * 2);
H.circle(v.X(sx), v.Y(sy), ringR, { stroke: curl >= 0 ? H.colors.accent : H.colors.warn, width: 2 });
v.dot(sx, sy, { r: 6, fill: H.colors.violet });
v.text("u", sx + ux * dirArrowLen + 0.1, sy + uy * dirArrowLen + 0.1, { color: H.colors.yellow, size: 13 });
H.text("Divergence & curl of a 2D vector field", 24, 32, { color: H.colors.ink, size: 18, weight: 700 });
H.text("F(x,y) = (0.6x - 0.9y + .4sin.8y,  0.9x + 0.6y).  div = outflow, curl = spin.", 24, 54, { color: H.colors.sub, size: 13 });
H.text("sample (x,y) = (" + sx.toFixed(2) + ", " + sy.toFixed(2) + ")", 24, 84, { color: H.colors.violet, size: 13 });
H.text("div F = " + div.toFixed(2) + "      curl F = " + curl.toFixed(2), 24, 104, { color: H.colors.ink, size: 13 });
H.text("u = (" + ux.toFixed(2) + ", " + uy.toFixed(2) + ")  -> direction of derivative", 24, 124, { color: H.colors.yellow, size: 13 });
H.legend([
  { label: "field F (arrows)", color: H.colors.accent },
  { label: "advected particles", color: H.colors.good },
  { label: "sample point", color: H.colors.violet },
  { label: "direction u", color: H.colors.yellow },
], 24, H.H - 84);

H.background();
const w = H.W, h = H.H;
const cam = H.cam3d({ scale: 30, dist: 20, pitch: -0.18, cy: h * 0.52 });
cam.yaw = 0.45 * t;

// One full turn of the helix unwinds/rewinds slightly so it breathes.
const N = 40;                       // base-pair rungs
const turns = 2.2;                  // helical turns across the strand
const radius = 2.2;
const ylo = -5.2, yhi = 5.2;
const twist = 0.22 * Math.sin(t * 0.6); // gentle live winding

// Base-pair color coding (A-T vs G-C) cycles deterministically.
const pairColors = [H.colors.good, H.colors.warn, H.colors.violet, H.colors.yellow];

// Collect every drawable (backbone balls + rung balls) for depth sorting.
const balls = [];
const rungs = [];

for (let i = 0; i < N; i++) {
  const s = i / (N - 1);
  const ang = s * H.TAU * turns + twist * i;
  const ypos = H.lerp(ylo, yhi, s);
  // Two antiparallel sugar-phosphate backbones, 180 deg apart.
  const a = [radius * Math.cos(ang), ypos, radius * Math.sin(ang)];
  const b = [radius * Math.cos(ang + H.PI), ypos, radius * Math.sin(ang + H.PI)];
  balls.push({ p: a, color: H.colors.accent, r: 0.34 });
  balls.push({ p: b, color: H.colors.accent2, r: 0.34 });

  // A travelling "replication / read" highlight sweeps up the molecule.
  const head = (t * 0.32) % 1;
  const lit = Math.abs(s - head) < 0.06;
  const c = pairColors[i % pairColors.length];
  rungs.push({ a: a, b: b, color: c, lit: lit });
}

// Draw rungs (base pairs) first as thin bonds behind the spheres.
for (let i = 0; i < rungs.length; i++) {
  const r = rungs[i];
  cam.line(r.a, r.b, {
    color: r.lit ? H.colors.ink : r.color,
    width: r.lit ? 3.2 : 1.5,
  });
}

// Depth-sort spheres far-to-near and shade them.
balls
  .map((o) => ({ p: o.p, color: o.color, r: o.r, depth: cam.project(o.p).depth }))
  .sort((m, n) => n.depth - m.depth)
  .forEach((o) => cam.sphere(o.p, o.r, { color: o.color }));

cam.axes(6);

// Labels + live readout.
const rise = 0.34;                  // nm per base pair (B-DNA)
const helixLen = (N * rise);
H.text("DNA double helix (B-form)", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("Two antiparallel strands wound into a right-handed helix.", 24, 52,
  { color: H.colors.sub, size: 13 });
H.text("read position = " + ((t * 0.32) % 1 * 100).toFixed(0) + "%   length ≈ "
  + helixLen.toFixed(1) + " nm", 24, 76, { color: H.colors.sub, size: 13 });
H.legend([
  { label: "strand 5'→3'", color: H.colors.accent },
  { label: "strand 3'→5'", color: H.colors.accent2 },
  { label: "base pair (A-T/G-C)", color: H.colors.good },
], 24, h - 70);

H.background();
const w = H.W, h = H.H;

// Lotka-Volterra parameters: prey grows (a), eaten (b); predator dies (c), fed (d).
const a = 1.1, b = 0.4, d = 0.1, c = 0.4;
// Integrate forward each frame from a fixed start so motion is a pure fn of t.
const dt = 0.02;
const steps = Math.min(900, Math.floor((t % 30) / dt) + 1);
let x = 10, y = 5;            // prey, predator populations
const trail = [[x, y]];
for (let i = 0; i < steps; i++) {
  const dx = a * x - b * x * y;
  const dy = d * x * y - c * y;
  // midpoint to keep the closed orbit from spiralling out numerically
  const xm = x + 0.5 * dt * dx;
  const ym = y + 0.5 * dt * dy;
  const dxm = a * xm - b * xm * ym;
  const dym = d * xm * ym - c * ym;
  x = Math.max(0.01, x + dt * dxm);
  y = Math.max(0.01, y + dt * dym);
  if (i % 3 === 0) trail.push([x, y]);
}

// LEFT: time series of both populations.
const vt = H.plot2d({
  xMin: 0, xMax: 30, yMin: 0, yMax: 28,
  box: { x: 60, y: 70, w: w * 0.52 - 70, h: h - 150 },
});
vt.grid(); vt.axes();
// Rebuild the two time series up to "now".
const preyPts = [], predPts = [];
let xx = 10, yy = 5;
for (let i = 0; i <= steps; i++) {
  const tm = i * dt;
  if (i % 2 === 0) { preyPts.push([tm, xx]); predPts.push([tm, yy]); }
  const dx = a * xx - b * xx * yy;
  const dy = d * xx * yy - c * yy;
  const xm = xx + 0.5 * dt * dx, ym = yy + 0.5 * dt * dy;
  const dxm = a * xm - b * xm * ym, dym = d * xm * ym - c * ym;
  xx = Math.max(0.01, xx + dt * dxm);
  yy = Math.max(0.01, yy + dt * dym);
}
vt.path(preyPts, { color: H.colors.good, width: 2.6 });
vt.path(predPts, { color: H.colors.warn, width: 2.6 });
vt.dot(Math.min(30, steps * dt), x, { r: 5, fill: H.colors.good });
vt.dot(Math.min(30, steps * dt), y, { r: 5, fill: H.colors.warn });
H.text("population", 60, 60, { color: H.colors.sub, size: 12 });
H.text("time", vt.box.x + vt.box.w - 26, vt.box.y + vt.box.h + 30,
  { color: H.colors.sub, size: 12 });

// RIGHT: phase portrait (predator vs prey) - the closed orbit.
const vp = H.plot2d({
  xMin: 0, xMax: 26, yMin: 0, yMax: 18,
  box: { x: w * 0.56 + 20, y: 70, w: w * 0.40 - 40, h: h - 150 },
});
vp.grid(); vp.axes();
vp.path(trail, { color: H.colors.accent, width: 2.2 });
// Equilibrium fixed point (c/d, a/b).
vp.dot(c / d, a / b, { r: 4, fill: H.colors.yellow, stroke: H.colors.bg });
vp.dot(x, y, { r: 6, fill: H.colors.accent2 });
H.text("predator", vp.box.x - 6, 60, { color: H.colors.sub, size: 12 });
H.text("prey →", vp.box.x + vp.box.w - 50, vp.box.y + vp.box.h + 30,
  { color: H.colors.sub, size: 12 });

// Title, caption, live readout, legend.
H.text("Lotka–Volterra predator–prey cycles", 24, 30,
  { color: H.colors.ink, size: 18, weight: 700 });
H.text("Prey booms feed predators; predators crash, prey recover — a closed loop.",
  24, 52, { color: H.colors.sub, size: 13 });
H.text("prey = " + x.toFixed(1) + "    predators = " + y.toFixed(1)
  + "    t = " + (steps * dt).toFixed(1) + "s",
  w * 0.56 + 20, 52, { color: H.colors.sub, size: 13 });
H.legend([
  { label: "prey (rabbits)", color: H.colors.good },
  { label: "predators (foxes)", color: H.colors.warn },
  { label: "phase orbit", color: H.colors.accent },
], 60, h - 46);

H.background();
const w = H.W, h = H.H;

// Action-potential waveform as a function of phase within a repeating spike.
// Resting -70 mV, threshold -55, peak +40, after-hyperpolarization -80.
const period = 4.0;                 // seconds between spikes (slowed for teaching)
const phase = (t % period);
function Vm(ph) {
  const rest = -70, thr = -55, peak = 40, ahp = -80;
  if (ph < 1.2) {                   // resting / slow depolarization to threshold
    return H.lerp(rest, thr, H.ease(ph / 1.2));
  } else if (ph < 1.55) {           // fast Na+ influx: depolarize to peak
    return H.lerp(thr, peak, H.ease((ph - 1.2) / 0.35));
  } else if (ph < 2.1) {            // K+ efflux: repolarize
    return H.lerp(peak, ahp, H.ease((ph - 1.55) / 0.55));
  } else if (ph < 2.9) {            // after-hyperpolarization recovers to rest
    return H.lerp(ahp, rest, H.ease((ph - 2.1) / 0.8));
  }
  return rest;
}
const v = Vm(phase);

// Plot the membrane potential trace over one cycle.
const view = H.plot2d({
  xMin: 0, xMax: period, yMin: -90, yMax: 50,
  box: { x: 64, y: 78, w: w - 230, h: h - 160 },
});
view.grid(); view.axes();

// Threshold and resting reference lines.
view.line(0, -55, period, -55, { color: H.colors.violet, width: 1.4, dash: [6, 5] });
view.text("threshold –55 mV", period * 0.62, -49,
  { color: H.colors.violet, size: 11 });
view.line(0, -70, period, -70, { color: H.colors.axis, width: 1.2, dash: [3, 5] });
view.text("rest –70 mV", period * 0.02, -66, { color: H.colors.sub, size: 11 });

// Full waveform (faint) + the swept-in portion (bright).
const full = [], swept = [];
const M = 160;
for (let i = 0; i <= M; i++) {
  const ph = (i / M) * period;
  const pt = [ph, Vm(ph)];
  full.push(pt);
  if (ph <= phase) swept.push(pt);
}
view.path(full, { color: H.hsl(205, 40, 45, 0.35), width: 2 });
if (swept.length > 1) view.path(swept, { color: H.colors.accent, width: 3 });
view.dot(phase, v, { r: 6, fill: H.colors.accent2 });

// Phase label that names the current ion event.
let stage = "resting", sc = H.colors.sub;
if (phase >= 1.2 && phase < 1.55) { stage = "depolarization (Na+ in)"; sc = H.colors.warn; }
else if (phase >= 1.55 && phase < 2.1) { stage = "repolarization (K+ out)"; sc = H.colors.accent; }
else if (phase >= 2.1 && phase < 2.9) { stage = "hyperpolarization (refractory)"; sc = H.colors.violet; }
else if (phase >= 0.7 && phase < 1.2) { stage = "approaching threshold"; sc = H.colors.good; }

// A small membrane channel diagram on the right that opens/closes with phase.
const mx = w - 140, my = h * 0.5;
H.text("membrane", mx - 20, my - 92, { color: H.colors.sub, size: 12 });
H.line(mx - 44, my - 70, mx + 44, my - 70, { color: H.colors.axis, width: 2 });
H.line(mx - 44, my + 70, mx + 44, my + 70, { color: H.colors.axis, width: 2 });
const naOpen = phase >= 1.2 && phase < 1.6;
const kOpen = phase >= 1.5 && phase < 2.3;
// Na+ channel
H.circle(mx - 22, my, 16, { stroke: H.colors.warn, width: 2, fill: naOpen ? H.hsl(350, 70, 40, 0.5) : "rgba(0,0,0,0)" });
H.text("Na⁺", mx - 33, my + 4, { color: H.colors.warn, size: 11 });
if (naOpen) H.arrow(mx - 22, my - 60, mx - 22, my + 18, { color: H.colors.warn, width: 2, head: 7 });
// K+ channel
H.circle(mx + 22, my, 16, { stroke: H.colors.accent, width: 2, fill: kOpen ? H.hsl(205, 70, 45, 0.5) : "rgba(0,0,0,0)" });
H.text("K⁺", mx + 13, my + 4, { color: H.colors.accent, size: 11 });
if (kOpen) H.arrow(mx + 22, my + 18, mx + 22, my + 84, { color: H.colors.accent, width: 2, head: 7 });

// Titles + live readout.
H.text("Neuron action potential", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("Membrane voltage spikes as Na⁺ rushes in, then K⁺ restores rest.",
  24, 52, { color: H.colors.sub, size: 13 });
H.text("Vm = " + v.toFixed(1) + " mV", 24, 76, { color: H.colors.accent2, size: 14, weight: 600 });
H.text("phase: " + stage, 200, 76, { color: sc, size: 13, weight: 600 });
H.text("mV", 30, 70, { color: H.colors.sub, size: 12 });
H.text("time (cycle)", view.box.x + view.box.w - 70, view.box.y + view.box.h + 30,
  { color: H.colors.sub, size: 12 });
H.legend([
  { label: "membrane potential Vm", color: H.colors.accent },
  { label: "Na⁺ influx", color: H.colors.warn },
  { label: "K⁺ efflux / AHP", color: H.colors.violet },
], 64, h - 46);

H.background();
const w = H.W, h = H.H;
// ---- Heat diffusion on a square plate, u_t = alpha * laplacian(u) ----
// Closed-form solution on [0,1]x[0,1] with fixed cold edges (u=0 on boundary):
// a hot Gaussian-ish initial bump decays as a sum of sine modes, each mode
// shrinking like exp(-alpha*pi^2*(m^2+n^2)*tau). Stable, never blows up.
const alpha = 0.18;                 // thermal diffusivity (arb. units)
const tau = (t % 14) * 1.0;         // simulation clock, loops every 14 s
// Plate pixel box
const M = 26;                       // grid cells per side
const plateX = 70, plateY = 96;
const plateW = Math.min(w - 320, h - 150);
const cell = plateW / M;
const plateH = plateW;
// Precompute a small set of Fourier amplitudes for an initial off-center hot spot.
const modes = [];
const MX = 5, MY = 5;
const cx0 = 0.38, cy0 = 0.42;       // initial hot-spot center (unit square)
for (let mx = 1; mx <= MX; mx++) {
  for (let my = 1; my <= MY; my++) {
    // amplitude ~ projection of a localized bump onto sin modes
    const amp =
      Math.sin(mx * Math.PI * cx0) *
      Math.sin(my * Math.PI * cy0) *
      Math.exp(-0.5 * (mx * mx + my * my) * 0.10);
    modes.push({ mx, my, amp, lam: (mx * mx + my * my) });
  }
}
// Temperature field T(x,y,tau) in [0,1]; track max for the readout.
const temp = (ux, uy) => {
  let s = 0;
  for (let k = 0; k < modes.length; k++) {
    const m = modes[k];
    s +=
      m.amp *
      Math.sin(m.mx * Math.PI * ux) *
      Math.sin(m.my * Math.PI * uy) *
      Math.exp(-alpha * Math.PI * Math.PI * m.lam * tau);
  }
  return s;
};
// Color ramp cold(blue) -> hot(red/white). v in [0,1].
const heatColor = (v) => {
  v = H.clamp(v, 0, 1);
  // blue(230) -> cyan -> yellow -> red(0), brighten toward the top end.
  const hue = H.lerp(235, 0, v);
  const light = H.lerp(22, 62, v);
  const sat = H.lerp(70, 92, v);
  return H.hsl(hue, sat, light);
};
// Normalize against the t=0 peak so the color scale is steady.
let peak0 = 1e-6;
for (let i = 0; i < M; i++) {
  for (let j = 0; j < M; j++) {
    const v = temp((i + 0.5) / M, (j + 0.5) / M);
    if (v > peak0) peak0 = v;
  }
}
let curMax = 0;
for (let j = 0; j < M; j++) {
  for (let i = 0; i < M; i++) {
    const ux = (i + 0.5) / M;
    const uy = (j + 0.5) / M;
    let v = temp(ux, uy) / peak0;
    if (v < 0) v = 0;                // temperature above ambient is nonnegative
    if (v > curMax) curMax = v;
    const px = plateX + i * cell;
    const py = plateY + (M - 1 - j) * cell; // flip so +y is up
    H.rect(px, py, cell + 0.8, cell + 0.8, { fill: heatColor(v) });
  }
}
// Plate frame
H.rect(plateX, plateY, plateW, plateH, { stroke: H.colors.axis, width: 1.6 });
// Axis ticks (physical plate coordinates 0..1)
for (let g = 0; g <= 1.0001; g += 0.25) {
  const gx = plateX + g * plateW;
  const gy = plateY + plateH;
  H.text(g.toFixed(2), gx, gy + 16, { color: H.colors.sub, size: 11, align: "center" });
  H.text(g.toFixed(2), plateX - 8, plateY + (1 - g) * plateH, { color: H.colors.sub, size: 11, align: "right", baseline: "middle" });
}
H.text("x", plateX + plateW / 2, plateY + plateH + 32, { color: H.colors.sub, size: 12, align: "center" });
H.text("y", plateX - 30, plateY + plateH / 2, { color: H.colors.sub, size: 12, align: "center", baseline: "middle" });
// ---- Color legend bar ----
const barX = plateX + plateW + 40, barY = plateY, barW = 22, barH = plateH;
const segs = 40;
for (let k = 0; k < segs; k++) {
  const v = 1 - k / segs;
  H.rect(barX, barY + (k / segs) * barH, barW, barH / segs + 0.8, { fill: heatColor(v) });
}
H.rect(barX, barY, barW, barH, { stroke: H.colors.axis, width: 1.2 });
H.text("hot", barX + barW + 8, barY + 6, { color: H.colors.warn, size: 12 });
H.text("cold", barX + barW + 8, barY + barH, { color: H.colors.accent, size: 12 });
H.text("T / T0", barX, barY - 12, { color: H.colors.sub, size: 12 });
// ---- Title + live readout ----
H.text("Heat diffusion across a plate", 24, 34, { color: H.colors.ink, size: 18, weight: 700 });
H.text("u_t = α ∇²u  —  a hot spot spreads and cools toward the edges", 24, 56, { color: H.colors.sub, size: 13 });
const peakPct = (curMax * 100);
H.text("t = " + tau.toFixed(2) + " s", barX - 4, barY + barH + 60, { color: H.colors.ink, size: 14, weight: 700 });
H.text("peak temp = " + peakPct.toFixed(1) + "% of T0", barX - 4, barY + barH + 82, { color: H.colors.accent2, size: 13 });
H.text("α = " + alpha.toFixed(2), barX - 4, barY + barH + 102, { color: H.colors.sub, size: 13 });

H.background();
// ---- Ideal gas: N atoms bouncing elastically inside a 3D box ----
const cam = H.cam3d({ scale: 30, dist: 16, pitch: -0.35, cy: H.H * 0.52 });
cam.yaw = 0.25 * t;                  // slow auto-spin so it reads as 3D
const L = 3.2;                        // half-box size (world units)
// Deterministic pseudo-random per-particle parameters (pure function of t-free
// seeds) so motion is smooth and reproducible each frame.
const N = 28;
const rand = (i, k) => {
  const s = Math.sin(i * 12.9898 + k * 78.233) * 43758.5453;
  return s - Math.floor(s);          // 0..1
};
// Continuous triangle wave: a particle bouncing elastically between walls at
// -lim and +lim, given a linearly advancing argument.
const tri = (val, lim) => {
  // continuous triangle wave bouncing in [-lim, lim] given a linear val
  const span = 2 * lim;
  let m = ((val % (2 * span)) + 2 * span) % (2 * span); // 0..2span
  if (m > span) m = 2 * span - m;     // 0..span
  return m - lim;                     // -lim..lim
};
// Draw box wireframe (depth-sorted edges look fine as plain lines)
const c = [
  [-L, -L, -L], [L, -L, -L], [L, L, -L], [-L, L, -L],
  [-L, -L, L], [L, -L, L], [L, L, L], [-L, L, L],
];
const edges = [
  [0,1],[1,2],[2,3],[3,0], [4,5],[5,6],[6,7],[7,4], [0,4],[1,5],[2,6],[3,7],
];
cam.grid(L, L, { color: H.colors.grid });
edges.forEach((e) => cam.line(c[e[0]], c[e[1]], { color: H.colors.axis, width: 1.3 }));
// Particle positions + speeds
const r = 0.16;
let vSum = 0, v2Sum = 0, vMax = 0, leftCount = 0;
const balls = [];
for (let i = 0; i < N; i++) {
  const sx = 0.4 + rand(i, 1) * 0.9;   // speed components (world units / s)
  const sy = 0.4 + rand(i, 2) * 0.9;
  const sz = 0.4 + rand(i, 3) * 0.9;
  const ph = rand(i, 4) * 100;         // phase offset
  const x = tri(sx * t + ph, L - r);
  const y = tri(sy * t + ph * 1.3, L - r);
  const z = tri(sz * t + ph * 0.7, L - r);
  const speed = Math.sqrt(sx * sx + sy * sy + sz * sz);
  vSum += speed;
  v2Sum += speed * speed;
  if (speed > vMax) vMax = speed;
  if (x < 0) leftCount++;              // instantaneous count in the x<0 half
  // color warm = fast, cool = slow
  const frac = H.clamp((speed - 0.7) / 1.6, 0, 1);
  const col = H.hsl(H.lerp(205, 25, frac), 85, H.lerp(58, 60, frac));
  balls.push({ p: [x, y, z], r: r, col: col, depth: cam.project([x, y, z]).depth });
}
balls.sort((a, b) => b.depth - a.depth).forEach((o) => cam.sphere(o.p, o.r, { color: o.col }));
// Faint divider plane at x=0 to make the left/right count meaningful.
cam.line([0, -L, -L], [0, -L, L], { color: H.colors.violet, width: 1 });
cam.line([0, -L, -L], [0, L, -L], { color: H.colors.violet, width: 1 });
cam.axes(L + 0.6);
const vAvg = vSum / N;
const v2Avg = v2Sum / N;          // mean square speed ⟨v²⟩ (this sets T, not ⟨v⟩²)
const rightCount = N - leftCount;
// ---- Title + live readout ----
H.text("Ideal gas in a box", 24, 34, { color: H.colors.ink, size: 18, weight: 700 });
H.text("N atoms in constant elastic motion — temperature ∝ mean kinetic energy", 24, 56, { color: H.colors.sub, size: 13 });
H.text("N = " + N + " atoms", 24, H.H - 100, { color: H.colors.accent, size: 13 });
H.text("⟨v⟩ = " + vAvg.toFixed(3) + " (arb.)", 24, H.H - 78, { color: H.colors.ink, size: 14, weight: 700 });
H.text("T ∝ ⟨v²⟩  →  " + v2Avg.toFixed(3), 24, H.H - 56, { color: H.colors.accent2, size: 13 });
H.text("left | right  =  " + leftCount + " | " + rightCount + "   (t = " + (t % 100).toFixed(1) + " s)", 24, H.H - 34, { color: H.colors.violet, size: 13 });
H.legend([
  { label: "fast (hot)", color: H.hsl(25, 85, 60) },
  { label: "slow (cool)", color: H.hsl(205, 85, 58) },
], H.W - 150, H.H - 70);

H.background();
// ---- Maxwell-Boltzmann speed distribution forming from samples ----
// Analytic 3D speed pdf (mass=kT=1 reduced units):
//   f(v) = sqrt(2/pi) * v^2 * exp(-v^2 / (2 a^2)) / a^3,   a = sqrt(kT/m)
// We let temperature breathe slowly and draw both the smooth curve and a live
// histogram of N pseudo-random samples that "fills in" toward the curve.
const T = 1.6 + 0.6 * Math.sin(t * 0.35);   // temperature (>0 always)
const a = Math.sqrt(T);                       // scale parameter
const vMaxAxis = 6;
const v = H.plot2d({ xMin: 0, xMax: vMaxAxis, yMin: 0, yMax: 0.7, pad: 56 });
v.grid(); v.axes();
const pdf = (x) => {
  if (x < 0) return 0;
  const a2 = a * a;
  return Math.sqrt(2 / Math.PI) * (x * x) * Math.exp(-(x * x) / (2 * a2)) / (a2 * a);
};
// ---- Histogram of samples (Box-Muller -> 3 normals -> speed) ----
const bins = 24;
const counts = new Array(bins).fill(0);
// Number of samples grows with time then holds — the distribution "forms".
const Nmax = 1400;
const N = Math.min(Nmax, Math.floor(60 + (t % 16) * 130));
const rnd = (k) => {
  const s = Math.sin(k * 12.9898) * 43758.5453;
  return s - Math.floor(s);
};
const normal = (k) => {
  // Box-Muller from two deterministic uniforms
  let u1 = rnd(k * 2 + 1); let u2 = rnd(k * 2 + 2);
  u1 = Math.min(Math.max(u1, 1e-6), 1 - 1e-6);
  return Math.sqrt(-2 * Math.log(u1)) * Math.cos(2 * Math.PI * u2);
};
let speedSum = 0, vrmsSum = 0;
for (let i = 0; i < N; i++) {
  const base = i * 3 + Math.floor(t) * 9973; // shuffle seed slowly with time
  const vx = a * normal(base + 1);
  const vy = a * normal(base + 2);
  const vz = a * normal(base + 3);
  const sp = Math.sqrt(vx * vx + vy * vy + vz * vz);
  speedSum += sp;
  vrmsSum += sp * sp;
  const b = Math.floor((sp / vMaxAxis) * bins);
  if (b >= 0 && b < bins) counts[b]++;
}
// Draw histogram bars (normalized to a density so they sit under the curve)
const binW = vMaxAxis / bins;
for (let b = 0; b < bins; b++) {
  const density = counts[b] / (N * binW);     // probability density estimate
  if (density <= 0) continue;
  const x0 = b * binW;
  H.rect(
    v.X(x0), v.Y(density), v.X(x0 + binW) - v.X(x0), v.Y(0) - v.Y(density),
    { fill: H.hsl(205, 70, 52, 0.45), stroke: H.hsl(205, 70, 66, 0.7), width: 1 }
  );
}
// Analytic curve on top
v.fn(pdf, { color: H.colors.accent2, width: 3 });
// Mark characteristic speeds: most-probable v_p = a*sqrt(2)
const vp = a * Math.SQRT2;
const vAvg = a * Math.sqrt(8 / Math.PI);
const vRms = a * Math.sqrt(3);
H.line(v.X(vp), v.Y(0), v.X(vp), v.Y(pdf(vp)), { color: H.colors.good, width: 2, dash: [5, 5] });
v.dot(vp, pdf(vp), { r: 5, fill: H.colors.good });
H.text("v_p", v.X(vp) + 6, v.Y(pdf(vp)) - 6, { color: H.colors.good, size: 12 });
// Axis labels
H.text("speed v (arb. units)", v.box.x + v.box.w / 2, v.box.y + v.box.h + 38, { color: H.colors.sub, size: 12, align: "center" });
H.text("f(v)", v.box.x - 40, v.box.y + 8, { color: H.colors.sub, size: 12 });
// ---- Title + live readouts ----
H.text("Maxwell–Boltzmann speed distribution", 24, 32, { color: H.colors.ink, size: 18, weight: 700 });
H.text("Histogram of " + N + " random molecular speeds filling in the analytic curve", 24, 54, { color: H.colors.sub, size: 13 });
const measAvg = N > 0 ? speedSum / N : 0;
const measRms = N > 0 ? Math.sqrt(vrmsSum / N) : 0;
H.legend([
  { label: "analytic f(v)", color: H.colors.accent2 },
  { label: "sampled histogram", color: H.hsl(205, 70, 60) },
  { label: "v_p (most probable)", color: H.colors.good },
], H.W - 230, 92);
H.text("T = " + T.toFixed(2) + "   N = " + N, H.W - 230, 168, { color: H.colors.ink, size: 13, weight: 700 });
H.text("⟨v⟩ ≈ " + measAvg.toFixed(2) + " (theory " + vAvg.toFixed(2) + ")", H.W - 230, 188, { color: H.colors.sub, size: 12 });
H.text("v_rms ≈ " + measRms.toFixed(2) + " (theory " + vRms.toFixed(2) + ")", H.W - 230, 206, { color: H.colors.sub, size: 12 });

H.background();
const v = H.plot2d({ xMin: -5, xMax: 5, yMin: -3.6, yMax: 3.6, pad: 50 });
const s = (1 - Math.cos(t * 0.8)) * 0.5;
const m00 = H.lerp(1, 2, s), m01 = H.lerp(0, 1, s);
const m10 = H.lerp(0, 1, s), m11 = H.lerp(1, 2, s);
const apply = (x, y) => [m00 * x + m01 * y, m10 * x + m11 * y];
for (let gx = -5; gx <= 5; gx++) {
  const pts = [];
  for (let gy = -4; gy <= 4; gy += 0.5) pts.push(apply(gx, gy));
  v.path(pts, { color: H.colors.grid, width: 1 });
}
for (let gy = -4; gy <= 4; gy++) {
  const pts = [];
  for (let gx = -5; gx <= 5; gx += 0.5) pts.push(apply(gx, gy));
  v.path(pts, { color: H.colors.grid, width: 1 });
}
v.axes();
const sq = [[0, 0], [1, 0], [1, 1], [0, 1]].map((p) => apply(p[0], p[1]));
v.path(sq, { color: H.colors.accent2, width: 2.4, close: true, fill: "rgba(244,162,89,0.18)" });
const ix = apply(1, 0), jx = apply(0, 1);
v.arrow(0, 0, ix[0], ix[1], { color: H.colors.accent, width: 3 });
v.arrow(0, 0, jx[0], jx[1], { color: H.colors.good, width: 3 });
v.text("i", ix[0] * 0.55 + 0.15, ix[1] * 0.55 - 0.2, { color: H.colors.accent, size: 14 });
v.text("j", jx[0] * 0.55 - 0.35, jx[1] * 0.55 + 0.1, { color: H.colors.good, size: 14 });
const e1 = [1 / Math.SQRT2, 1 / Math.SQRT2];
const e2 = [1 / Math.SQRT2, -1 / Math.SQRT2];
const lam1 = H.lerp(1, 3, s), lam2 = 1;
v.line(-4 * e1[0], -4 * e1[1], 4 * e1[0], 4 * e1[1], { color: H.colors.violet, width: 1.2, dash: [6, 6] });
v.line(-4 * e2[0], -4 * e2[1], 4 * e2[0], 4 * e2[1], { color: H.colors.yellow, width: 1.2, dash: [6, 6] });
v.arrow(0, 0, lam1 * e1[0], lam1 * e1[1], { color: H.colors.violet, width: 3.2 });
v.arrow(0, 0, lam2 * e2[0], lam2 * e2[1], { color: H.colors.yellow, width: 3.2 });
v.text("L1 = " + lam1.toFixed(2), lam1 * e1[0] + 0.2, lam1 * e1[1] + 0.3, { color: H.colors.violet, size: 13 });
v.text("L2 = " + lam2.toFixed(2), lam2 * e2[0] + 0.3, lam2 * e2[1] - 0.25, { color: H.colors.yellow, size: 13 });
const det = m00 * m11 - m01 * m10;
H.text("2x2 matrix transforming the plane", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("Eigenvectors keep their direction; the square's area scales by det.", 24, 52, { color: H.colors.sub, size: 13 });
H.text("M = [[" + m00.toFixed(2) + ", " + m01.toFixed(2) + "], [" + m10.toFixed(2) + ", " + m11.toFixed(2) + "]]", 24, 78, { color: H.colors.accent, size: 13 });
H.text("det(M) = " + det.toFixed(2) + "   (unit-square area)", 24, 98, { color: H.colors.accent2, size: 13 });
H.legend([
  { label: "i, j (basis images)", color: H.colors.accent },
  { label: "eigvec L1 span", color: H.colors.violet },
  { label: "eigvec L2 span", color: H.colors.yellow },
], H.W - 210, 96);

H.background();
const v = H.plot2d({ xMin: -1.5, xMax: 6.5, yMin: -1.5, yMax: 5, pad: 50 });
v.grid();
v.axes();
const a = [4, 1];
const ang = 1.05 + 0.85 * Math.sin(t * 0.6);
const bMag = 3.2;
const b = [bMag * Math.cos(ang), bMag * Math.sin(ang)];
const sum = [a[0] + b[0], a[1] + b[1]];
v.line(a[0], a[1], sum[0], sum[1], { color: H.colors.good, width: 1.4, dash: [5, 5] });
v.line(b[0], b[1], sum[0], sum[1], { color: H.colors.accent, width: 1.4, dash: [5, 5] });
v.arrow(0, 0, sum[0], sum[1], { color: H.colors.violet, width: 3 });
v.text("a + b", sum[0] + 0.15, sum[1] + 0.25, { color: H.colors.violet, size: 14 });
v.arrow(0, 0, a[0], a[1], { color: H.colors.accent, width: 3.4 });
v.arrow(0, 0, b[0], b[1], { color: H.colors.good, width: 3.4 });
v.text("a", a[0] * 0.6 + 0.1, a[1] * 0.6 - 0.25, { color: H.colors.accent, size: 15 });
v.text("b", b[0] * 0.6 - 0.3, b[1] * 0.6 + 0.2, { color: H.colors.good, size: 15 });
const aLen2 = a[0] * a[0] + a[1] * a[1];
const aLen = Math.sqrt(aLen2);
const dot = a[0] * b[0] + a[1] * b[1];
const scal = dot / aLen2;
