v.line(b[0], b[1], proj[0], proj[1], { color: H.colors.warn, width: 1.6, dash: [4, 4] });
v.line(0, 0, proj[0], proj[1], { color: H.colors.accent2, width: 5 });
v.dot(proj[0], proj[1], { r: 5, fill: H.colors.accent2 });
v.text("proj_a b", proj[0] - 0.2, proj[1] - 0.35, { color: H.colors.accent2, size: 13 });
const scalarProj = dot / aLen;
const cosA = dot / (aLen * bMag);
H.text("Vector addition + dot product as projection", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("a+b closes the parallelogram; a.b measures b's shadow on a.", 24, 52, { color: H.colors.sub, size: 13 });
H.text("a = (" + a[0].toFixed(1) + ", " + a[1].toFixed(1) + ")   b = (" + b[0].toFixed(2) + ", " + b[1].toFixed(2) + ")", 24, 78, { color: H.colors.sub, size: 13 });
H.text("a . b = " + dot.toFixed(2) + " = |a||b|cos(t),  cos = " + cosA.toFixed(2), 24, 98, { color: H.colors.accent2, size: 13 });
H.text("scalar proj = a.b/|a| = " + scalarProj.toFixed(2), 24, 118, { color: H.colors.warn, size: 13 });
H.legend([
  { label: "a", color: H.colors.accent },
