H.background();
const cam = H.cam3d({ scale: 52, dist: 14, pitch: -0.5, cy: H.H * 0.56 });
cam.yaw = 0.25 * t;
cam.grid(4, 1);
const theta = t * 0.9;
const c = Math.cos(theta), sN = Math.sin(theta);
const rot = (p) => [
  c * p[0] + sN * p[2],
  p[1],
  -sN * p[0] + c * p[2],
];
cam.line([0, -2.4, 0], [0, 2.4, 0], { color: H.colors.violet, width: 2.4 });
cam.sphere([0, 2.4, 0], 0.12, { color: H.colors.violet });
const half = 1.1;
const corners = [];
for (let xi = -1; xi <= 1; xi += 2)
  for (let yi = -1; yi <= 1; yi += 2)
    for (let zi = -1; zi <= 1; zi += 2)
      corners.push(rot([xi * half, yi * half, zi * half]));
const edges = [[0,1],[0,2],[0,4],[1,3],[1,5],[2,3],[2,6],[3,7],[4,5],[4,6],[5,7],[6,7]];
edges.forEach((e) => cam.line(corners[e[0]], corners[e[1]], { color: H.colors.accent, width: 1.8 }));
const v0 = [1.8, 0.6, 0];
const vr = rot(v0);
const o = cam.project([0, 0, 0]);
const g = cam.project(v0);
const p = cam.project(vr);
H.arrow(o.x, o.y, g.x, g.y, { color: H.colors.sub, width: 1.6 });
H.arrow(o.x, o.y, p.x, p.y, { color: H.colors.accent2, width: 3 });
H.text("v", p.x + 6, p.y - 4, { color: H.colors.accent2, size: 14 });
const trail = [];
